CREATE TABLE students (
  student_id INT PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  city VARCHAR(60),
  marks INT
);
INSERT INTO students VALUES
  (1, 'Asha', 'Bengaluru', 85),
  (2, 'Ravi', 'Mysuru', 72),
  (3, 'Neha', 'Bengaluru', 91);
SELECT name, marks FROM students;
SELECT DISTINCT city FROM students;

SELECT name, marks FROM students WHERE marks >= 80;
SELECT name FROM students WHERE city IN ('Bengaluru', 'Mysuru');
SELECT name FROM students WHERE name LIKE 'A%';
SELECT name FROM students WHERE marks BETWEEN 70 AND 90;
SELECT name FROM students WHERE city IS NOT NULL;

INSERT INTO students (student_id, name, city, marks)
VALUES (4, 'Imran', 'Hubballi', 78);

START TRANSACTION;
SELECT * FROM students WHERE student_id = 4;
UPDATE students SET marks = 82 WHERE student_id = 4;
SELECT * FROM students WHERE student_id = 4;
ROLLBACK;

